/*
 * A381704  Fibonacci numbers having a Fibonacci number of 1's in their binary
 *          representation.
 * https://oeis.org/A381704
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 16, u32 n <= 20, u64 n <= 22, u128 n <= 26,
 *            big any n
 * Helpers:   seq_alloc, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) = the n‑th Fibonacci number whose binary Hamming weight is a
 * Fibonacci number (including 0).  The sequence is generated by
 * searching successive Fibonacci numbers until the nth qualifying
 * member is found.  The result is returned for any n ≥ 1. */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"

/* Pre–compute Fibonacci numbers up to MAX_BITS for popcount test. */
#define MAX_BITS 200000
static bool fib_bits[MAX_BITS + 1];
static bool fib_bits_computed = false;

static void compute_fib_bits(void)
{
    if (fib_bits_computed) return;
    unsigned long long a = 0, b = 1;
    fib_bits[0] = true;
    fib_bits[1] = true;
    while (true) {
        unsigned long long c = a + b;
        if (c > (unsigned long long)MAX_BITS) break;
        fib_bits[(size_t)c] = true;
        a = b;
        b = c;
    }
    fib_bits_computed = true;
}

/* Popcount for seq_t.  Works for built‑in and arbitrary‑precision types. */
static idx_t popcount_seq(seq_t x)
{
    idx_t cnt = 0;
    while (x != (seq_t)0) {
        cnt += (idx_t)(x & (seq_t)1);
        x >>= 1;
    }
    return cnt;
}

/* Dynamic cache of qualifying Fibonacci numbers. */
static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_size = 0;

static void ensure_cache(size_t need)
{
    if (need <= cache_cap) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    if (new_cap < need) new_cap = need;
    seq_t *tmp = seq_realloc(cache, cache_cap, new_cap);
    cache = tmp;
    cache_cap = new_cap;
}

/* State for generating Fibonacci numbers on demand. */
static seq_t prev_fib = (seq_t)0;
static seq_t cur_fib  = (seq_t)1;
static idx_t last_index = 1;      /* index of cur_fib (F1) */

/* Information about the last added value (used to skip duplicates). */
static seq_t last_added = (seq_t)0;
static bool have_last_added = false;

/* One‑time initialization of static data. */
static bool initialized = false;
static void init_static_state(void)
{
    if (initialized) return;
    compute_fib_bits();

    cache = seq_alloc(16);
    cache_cap = 16;
    cache_size = 0;

    /* Seed with F0 */
    idx_t pc = popcount_seq(prev_fib);
    if (pc <= (idx_t)MAX_BITS && fib_bits[pc]) {
        cache[cache_size++] = prev_fib;
        last_added = prev_fib;
        have_last_added = true;
    }

    /* Seed with F1 */
    pc = popcount_seq(cur_fib);
    if (pc <= (idx_t)MAX_BITS && fib_bits[pc]) {
        if (!have_last_added || cur_fib != last_added) {
            cache[cache_size++] = cur_fib;
            last_added = cur_fib;
            have_last_added = true;
        }
    }

    initialized = true;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* undefined for offset 0, return 0 */
    init_static_state();

    /* Generate Fibonacci numbers until we have at least n qualifying terms. */
    while (cache_size < (size_t)n) {
        seq_t next_fib = prev_fib + cur_fib;
        idx_t next_index = last_index + 1;

        /* Check popcount */
        idx_t pc = popcount_seq(next_fib);
        if (pc <= (idx_t)MAX_BITS && fib_bits[pc]) {
            if (!have_last_added || next_fib != last_added) {
                ensure_cache(cache_size + 1);
                cache[cache_size++] = next_fib;
                last_added = next_fib;
                have_last_added = true;
            }
        }

        /* Advance Fibonacci state */
        prev_fib = cur_fib;
        cur_fib = next_fib;
        last_index = next_index;
    }

    return cache[n - 1];
}
